import sys

def main():
    import sys
    import itertools

    input = sys.stdin.read().split()
    n = int(input[0])
    data = [(int(input[2*i+1]), int(input[2*i+2])) for i in range(n)]

    edges = []
    used = [False] * n

    def find_unused():
        for i in range(n):
            if not used[i]:
                return i
        return None

    while True:
        start = find_unused()
        if start is None:
            break
        stack = [start]
        path = []
        while stack:
            current = stack.pop()
            if used[current]:
                continue
            used[current], degree, xor_sum = True, data[current]
            neighbors = set()
            for i in range(n):
                if data[i][0] > 0 and not used[i]:
                    if degree > 0 and (xor_sum ^ i) == data[i][1]:
                        degree -= 1
                        data[i] = (data[i][0] - 1, data[i][1] ^ current)
                        neighbors.add(i)
                        stack.append(i)
            path.extend([(current, neighbor) for neighbor in neighbors])
        edges.extend(path)

    print(len(edges))
    for a, b in edges:
        print(a, b)

main()
